package br.com.luvi.financaspessoais.dashboard.controller; import br.com.luvi.financaspessoais.dashboard.dto.DashboardResponse; import br.com.luvi.financaspessoais.dashboard.service.DashboardService; import br.com.luvi.financaspessoais.usuario.service.UsuarioService; import org.springframework.security.core.Authentication; import org.springframework.web.bind.annotation.*; import java.time.LocalDate; @RestController @RequestMapping("/api/dashboard") public class DashboardController{private final DashboardService service;private final UsuarioService usuarios;public DashboardController(DashboardService s,UsuarioService u){service=s;usuarios=u;}@GetMapping public DashboardResponse obter(@RequestParam(required=false)Integer mes,@RequestParam(required=false)Integer ano,@RequestParam(required=false)Long contaId,@RequestParam(required=false)Long grupoId,Authentication a){var h=LocalDate.now();return service.obter(mes==null?h.getMonthValue():mes,ano==null?h.getYear():ano,contaId,grupoId,usuarios.atual(a.getName()));}}